    18	    {
    19	        using(StreamWriter sw = new StreamWriter(LogFileName(), true))
    20	        {
    21	            sw.WriteLine(isInnerException ? "INNER EXCEPTION" : $"EXCEPTION: {DateTime.Now}");
    22	            sw.WriteLine(new string(isInnerException ? '-' : '=', 40));
    23	            sw.WriteLine($"{exception.Message}");
    24	            sw.WriteLine($"{exception.StackTrace}");
    25	
    26	            sw.WriteLine();
    27	        }
    28	
    29	        if(exception.InnerException != null)
    30	        {
    31	            Log(exception.InnerException, true);
    32	        }
    33	    }
    34	
    35	    private static string LogFileName()
    36	    {
    37	        return Path.Combine(AppDomain.CurrentDomain.BaseDirectory, LOG_FILE_DIRECTORY, $"RPG_{DateTime.Now:yyyyMMdd}.log");
