     8	public class Inventory
     9	{
    10	    private readonly List<GameItem> _backingInventory = new List<GameItem>();
    11	    private readonly List<GroupedInventoryItem> _backingGroupedInventoryItems = new List<GroupedInventoryItem>();
    12	    public IReadOnlyList<GameItem> Items => _backingInventory.AsReadOnly();
    13	    [JsonIgnore]
    14	    public IReadOnlyList<GroupedInventoryItem> GroupedInventory => _backingGroupedInventoryItems.AsReadOnly();
