    17	    [JsonIgnore]
    18	    public IReadOnlyList<GameItem> Consumables => _backingInventory.ItemsThatAre(GameItem.ItemCategory.Consumable).AsReadOnly();
    19	    [JsonIgnore]
    20	    public bool HasConsumable => Consumables.Any();
    21	
    22	    public Inventory(IEnumerable<GameItem> items = null)
    23	    {
    24	        if(items == null)
    25	        {
    26	            return;
    27	        }
    28	        foreach(GameItem item in items)
    29	        {
    30	            _backingInventory.Add(item);
    31	            AddItemToGroupedInventory(item);
    32	        }
    33	    }
    34	
    35	    public bool HasAllTheseItems(IEnumerable<ItemQuantity> items)
    36	    {
    37	        return items.All(item => Items.Count(i => i.ItemTypeId == item.ItemID) >= item.Quantity);
    38	    }
    39	    private void AddItemToGroupedInventory(GameItem item)
    40	    {
    41	        if (item.IsUnique)
    42	        {
    43	            _backingGroupedInventoryItems.Add(new GroupedInventoryItem(item, 1));
    44	        }
    45	        else
    46	        {
    47	            if(_backingGroupedInventoryItems.All(gi => gi.Item.ItemTypeId != item.ItemTypeId))
    48	            {
    49	                _backingGroupedInventoryItems.Add(new GroupedInventoryItem(item , 0));
    50	            }
    51	            _backingGroupedInventoryItems.First(gi => gi.Item.ItemTypeId == item.ItemTypeId).Quantity++;
    52	        }
    53	    }
