     1	using D20Tek.DiceNotation;
     2	using D20Tek.DiceNotation.DieRoller;
     3	using System;
     4	
     5	namespace Engine.Core;
     6	public class DiceService : IDiceService
     7	{
     8	    private static readonly IDiceService s_instance = new DiceService();
     9	
    10	    /// <summary>
    11	    /// Make constructor private to implement singleton pattern.
    12	    /// </summary>
    13	    private DiceService()
    14	    {
    15	    }
    16	
    17	    /// <summary>
    18	    /// Static singleton property
    19	    /// </summary>
    20	    public static IDiceService Instance => s_instance;
    21	
    22	    //--- IDiceService implementation
    23	
    24	    public IDice Dice { get; } = new Dice();
    25	
    26	    public IDieRoller DieRoller { get; private set; } = new RandomDieRoller();
    27	
    28	    public IDiceConfiguration Configuration => Dice.Configuration;
    29	
    30	    public IDieRollTracker RollTracker { get; private set; } = null;
    31	
    32	    public void Configure(RollerType rollerType, bool enableTracker = false, int constantValue = 1)
    33	    {
    34	        RollTracker = enableTracker ? new DieRollTracker() : null;
    35	
    36	        switch (rollerType)
    37	        {
    38	            case RollerType.Random:
    39	                DieRoller = new RandomDieRoller(RollTracker);
    40	                break;
    41	            case RollerType.Crypto:
    42	                DieRoller = new CryptoDieRoller(RollTracker);
    43	                break;
    44	            case RollerType.MathNet:
    45	                DieRoller = new MathNetDieRoller(RollTracker);
    46	                break;
    47	            case RollerType.Constant:
    48	                DieRoller = new ConstantDieRoller(constantValue);
    49	                break;
    50	            default:
    51	                throw new ArgumentOutOfRangeException(nameof(rollerType));
    52	        }
    53	    }
    54	
    55	    public DiceResult Roll(string diceNotation) => Dice.Roll(diceNotation, DieRoller);
    56	
    57	    public DiceResult Roll(int sides, int numDice = 1, int modifier = 0)
    58	    {
    59	        DiceResult result = Dice.Dice(sides, numDice).Constant(modifier).Roll(DieRoller);
    60	        Dice.Clear();
    61	
    62	        return result;
    63	    }
    64	}

