     1	namespace TestEngine.Models;
     2	
     3	using System;
     4	using System.Collections.Generic;
     5	using System.Linq;
     6	using Engine.Factories;
     7	using Engine.Models;
     8	using Engine.Services;
     9	using Microsoft.VisualStudio.TestTools.UnitTesting;
    10	
    11	[TestClass]
    12	public class TestInventory
    13	{
    14	    [TestMethod]
    15	    public void Test_Instantiate()
    16	    {
    17	        Inventory inventory = new Inventory();
    18	
    19	        Assert.AreEqual(0, inventory.Items.Count);
    20	    }
    21	
    22	    [TestMethod]
    23	    public void Test_AddItem()
    24	    {
    25	        Inventory inventory = new Inventory();
    26	
    27	        Inventory inventory1 = inventory.AddItemFromFactory(3001);
    28	
    29	        Assert.AreEqual(1, inventory1.Items.Count);
    30	    }
    31	
    32	    [TestMethod]
    33	    public void Test_AddItems()
    34	    {
    35	        Inventory inventory = new Inventory();
    36	
    37	        List<GameItem> itemsToAdd = new List<GameItem>();
    38	        itemsToAdd.Add(ItemFactory.CreateGameItem(3001));
    39	        itemsToAdd.Add(ItemFactory.CreateGameItem(3002));
    40	
    41	        Inventory inventory1 =
    42	            inventory.AddItems(itemsToAdd);
    43	
    44	        Assert.AreEqual(2, inventory1.Items.Count);
    45	
    46	        // Notice the used of chained AddItemFromFactory() calls
    47	        Inventory inventory2 =
    48	            inventory1
    49	                .AddItemFromFactory(3001)
    50	                .AddItemFromFactory(3002);
    51	
    52	        Assert.AreEqual(4, inventory2.Items.Count);
    53	    }
    54	
    55	    [TestMethod]
    56	    public void Test_AddItemQuantities()
    57	    {
    58	        Inventory inventory = new Inventory();
    59	
    60	        Inventory inventory1 =
    61	            inventory.AddItems(new List<ItemQuantity> {new ItemQuantity(ItemFactory.CreateGameItem(1001), 3)});
    62	
    63	        Assert.AreEqual(3, inventory1.Items.Count(i => i.ItemTypeId == 1001));
    64	
    65	        Inventory inventory2 =
    66	            inventory1.AddItemFromFactory(1001);
    67	
    68	        Assert.AreEqual(4, inventory2.Items.Count(i => i.ItemTypeId == 1001));
    69	
    70	        Inventory inventory3 =
    71	            inventory2.AddItems(new List<ItemQuantity> {new ItemQuantity(ItemFactory.CreateGameItem(1002), 1)});
    72	
    73	        Assert.AreEqual(4, inventory3.Items.Count(i => i.ItemTypeId == 1001));
    74	        Assert.AreEqual(1, inventory3.Items.Count(i => i.ItemTypeId == 1002));
    75	    }
    76	
    77	    [TestMethod]
    78	    public void Test_RemoveItem()
    79	    {
    80	        Inventory inventory = new Inventory();
    81	
    82	        GameItem item1 = ItemFactory.CreateGameItem(3001);
    83	        GameItem item2 = ItemFactory.CreateGameItem(3002);
    84	
    85	        Inventory inventory1 =
    86	            inventory.AddItems(new List<GameItem> {item1, item2});
    87	
    88	        Inventory inventory2 =
    89	            inventory1.RemoveItem(item1);
    90	
    91	        Assert.AreEqual(1, inventory2.Items.Count);
    92	    }
    93	
    94	    [TestMethod]
    95	    public void Test_RemoveItems()
    96	    {
    97	        Inventory inventory = new Inventory();
    98	
    99	        GameItem item1 = ItemFactory.CreateGameItem(3001);
   100	        GameItem item2 = ItemFactory.CreateGameItem(3002);
   101	        GameItem item3 = ItemFactory.CreateGameItem(3002);
   102	
   103	        Inventory inventory1 =
   104	            inventory.AddItems(new List<GameItem> {item1, item2, item3});
   105	
   106	        Inventory inventory2 =
   107	            inventory1.RemoveItems(new List<GameItem> {item2, item3});
   108	
   109	        Assert.AreEqual(1, inventory2.Items.Count);
   110	    }
   111	
   112	    [TestMethod]
   113	    public void Test_CategorizedItemProperties()
   114	    {
   115	        // Initial empty inventory
   116	        Inventory inventory = new Inventory();
   117	
   118	        Assert.AreEqual(0, inventory.Weapons.Count);
   119	        Assert.AreEqual(0, inventory.Consumables.Count);
   120	
   121	        // Add a pointy stick (weapon)
   122	        Inventory inventory1 = inventory.AddItemFromFactory(1001);
   123	
   124	        Assert.AreEqual(1, inventory1.Weapons.Count);
   125	        Assert.AreEqual(0, inventory1.Consumables.Count);
   126	
   127	        // Add oats (NOT a consumable)
   128	        Inventory inventory2 = inventory1.AddItemFromFactory(3001);
   129	
   130	        Assert.AreEqual(1, inventory2.Weapons.Count);
   131	        Assert.AreEqual(0, inventory2.Consumables.Count);
   132	
   133	        // Add a rusty sword (weapon)
   134	        Inventory inventory3 = inventory2.AddItemFromFactory(1002);
   135	
   136	        Assert.AreEqual(2, inventory3.Weapons.Count);
   137	        Assert.AreEqual(0, inventory3.Consumables.Count);
   138	
   139	        // Add a granola bar (IS a consumable)
   140	        Inventory inventory4 = inventory3.AddItemFromFactory(2001);
   141	
   142	        Assert.AreEqual(2, inventory4.Weapons.Count);
   143	        Assert.AreEqual(1, inventory4.Consumables.Count);
   144	    }
   145	
   146	    [TestMethod]
   147	    public void Test_RemoveItemQuantities()
   148	    {
   149	        // Initial empty inventory
   150	        Inventory inventory = new Inventory();
   151	
   152	        Assert.AreEqual(0, inventory.Weapons.Count);
   153	        Assert.AreEqual(0, inventory.Consumables.Count);
   154	
   155	        Inventory inventory2 =
   156	            inventory
   157	                .AddItemFromFactory(1001)
   158	                .AddItemFromFactory(1002)
   159	                .AddItemFromFactory(1002)
   160	                .AddItemFromFactory(1002)
   161	                .AddItemFromFactory(1002)
   162	                .AddItemFromFactory(3001)
   163	                .AddItemFromFactory(3001);
   164	
   165	        Assert.AreEqual(1, inventory2.Items.Count(i => i.ItemTypeId == 1001));
   166	        Assert.AreEqual(4, inventory2.Items.Count(i => i.ItemTypeId == 1002));
   167	        Assert.AreEqual(2, inventory2.Items.Count(i => i.ItemTypeId == 3001));
   168	
   169	        Inventory inventory3 =
   170	            inventory2
   171	                .RemoveItems(new List<ItemQuantity> {new ItemQuantity(ItemFactory.CreateGameItem(1002), 2)});
   172	
   173	        Assert.AreEqual(1, inventory3.Items.Count(i => i.ItemTypeId == 1001));
   174	        Assert.AreEqual(2, inventory3.Items.Count(i => i.ItemTypeId == 1002));
   175	        Assert.AreEqual(2, inventory3.Items.Count(i => i.ItemTypeId == 3001));
   176	
   177	        Inventory inventory4 =
   178	            inventory3
   179	                .RemoveItems(new List<ItemQuantity> {new ItemQuantity(ItemFactory.CreateGameItem(1002), 1)});
   180	
   181	        Assert.AreEqual(1, inventory4.Items.Count(i => i.ItemTypeId == 1001));
   182	        Assert.AreEqual(1, inventory4.Items.Count(i => i.ItemTypeId == 1002));
   183	        Assert.AreEqual(2, inventory4.Items.Count(i => i.ItemTypeId == 3001));
   184	    }
   185	
   186	    [TestMethod]
   187	    [ExpectedException(typeof(InvalidOperationException))]
   188	    public void Test_RemoveItemQuantities_RemoveTooMany()
   189	    {
   190	        // Initial empty inventory
   191	        Inventory inventory = new Inventory();
   192	
   193	        Assert.AreEqual(0, inventory.Weapons.Count);
   194	        Assert.AreEqual(0, inventory.Consumables.Count);
   195	
   196	        Inventory inventory2 =
   197	            inventory
   198	                .AddItemFromFactory(1001)
   199	                .AddItemFromFactory(1002)
   200	                .AddItemFromFactory(1002)
   201	                .AddItemFromFactory(1002)
   202	                .AddItemFromFactory(1002)
   203	                .AddItemFromFactory(3001)
   204	                .AddItemFromFactory(3001);
